function ContentView({issues}:{issues:Issue[]}){const contentIssues=issues.filter(x=>x.category==='Content'||x.ruleCode.includes('ALT')||x.ruleCode.includes('TITLE'));return <><PageTitle icon={FileText} title="محتوا" description="کیفیت محتوا با word count، عنوان، متا و تشخیص شباهت بررسی می‌شود."/><Panel><div className="panel-title"><div><h3>مشکلات محتوایی</h3><p>توصیه‌ها از Rule Engine قطعی می‌آیند.</p></div></div><div className="issue-list">{contentIssues.map(x=><IssueRow key={x.id} issue={x}/>)}{!contentIssues.length&&<div className="mini-empty">برای این snapshot مشکل محتوایی ثبت نشده است.</div>}</div></Panel></>}
